-- Migration 009 rollback: restore id as the klines primary key.
--
-- This restores schema shape only. The DBaaS snapshot is the data recovery
-- path. Each table is checked before a statement is prepared.

SET @table_name = 'klines_m1';
SET @pk_sql = IF(NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @table_name AND TABLE_TYPE = 'BASE TABLE'), CONCAT('SELECT ''', @table_name, ' absent'' AS rollback_note'), IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = @table_name AND CONSTRAINT_NAME = 'PRIMARY' AND COLUMN_NAME = 'id') = 1 AND NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = @table_name AND INDEX_NAME = CONCAT('uq_', @table_name, '_id')), CONCAT('SELECT ''', @table_name, ' already restored'' AS rollback_note'), CONCAT('ALTER TABLE ', @table_name, ' DROP PRIMARY KEY, DROP INDEX uq_', @table_name, '_id, ADD PRIMARY KEY (id), ALGORITHM=INPLACE, LOCK=NONE')));
PREPARE pk_stmt FROM @pk_sql; EXECUTE pk_stmt; DEALLOCATE PREPARE pk_stmt;

